-- Replace the initial placeholders with operational legal-document templates.
-- Provider identity is synchronized from marketplace_provider_settings by the
-- existing trigger; configurable prices, fees, and payout periods are referred
-- to as the values displayed at the time of each transaction.
with templates(document_type, title, summary, content_html) as (
  values
    (
      'terms_of_service',
      'ข้อกำหนดการใช้บริการ E-KRU Marketplace',
      'เงื่อนไขการเข้าถึงบัญชี การซื้อขาย การใช้เนื้อหา และความรับผิดชอบบน E-KRU Marketplace',
      $html$
        <h2>1. การยอมรับข้อกำหนด</h2>
        <p>ข้อกำหนดนี้ใช้กับผู้เยี่ยมชม สมาชิก ผู้ซื้อ ผู้ขาย โรงเรียน และผู้ใช้บริการ E-KRU Marketplace (“แพลตฟอร์ม”) การสมัครบัญชี กดตกลง สั่งซื้อ อัปโหลด หรือใช้บริการ ถือว่าผู้ใช้ได้อ่านและยอมรับข้อกำหนดและนโยบายที่เกี่ยวข้อง หากผู้ใช้ดำเนินการแทนองค์กร ผู้ใช้รับรองว่ามีอำนาจผูกพันองค์กรนั้น</p>
        <h2>2. บัญชีและความปลอดภัย</h2>
        <ul><li>ผู้ใช้ต้องให้ข้อมูลที่ถูกต้อง เป็นปัจจุบัน และไม่สวมรอยบุคคลอื่น</li><li>ผู้ใช้รับผิดชอบการรักษารหัสผ่าน PIN และอุปกรณ์ที่ใช้เข้าสู่ระบบ และต้องแจ้งผู้ให้บริการทันทีเมื่อสงสัยว่าบัญชีถูกใช้โดยไม่ได้รับอนุญาต</li><li>แพลตฟอร์มอาจขอข้อมูลยืนยันเพิ่มเติม จำกัด ระงับ หรือยกเลิกบัญชีเมื่อพบความเสี่ยง การทุจริต การละเมิดกฎหมาย หรือละเมิดนโยบาย โดยจะแจ้งเหตุและช่องทางชี้แจงเมื่อทำได้และไม่กระทบการตรวจสอบ</li></ul>
        <h2>3. บทบาทของแพลตฟอร์ม</h2>
        <p>แพลตฟอร์มเป็นพื้นที่กลางสำหรับค้นหา ซื้อ ขาย ส่งมอบ และจัดการสิทธิใช้ทรัพยากรการศึกษา สินค้าบางรายการจัดทำโดยผู้ขายอิสระ ผู้ขายเป็นผู้รับผิดชอบความถูกต้อง คุณภาพ สิทธิในเนื้อหา และคำรับรองของสินค้านั้น เว้นแต่ระบุชัดว่าเป็นสินค้าทางการของผู้ให้บริการ</p>
        <h2>4. คำสั่งซื้อและการชำระเงิน</h2>
        <p>ราคา ภาษี ค่าธรรมเนียม ขอบเขต License และยอดรวมที่แสดงก่อนยืนยันคำสั่งซื้อเป็นเงื่อนไขของรายการนั้น คำสั่งซื้อสมบูรณ์เมื่อระบบยืนยันการชำระเงิน แพลตฟอร์มอาจยกเลิกรายการที่ชำระไม่สำเร็จ ซ้ำซ้อน ผิดปกติ หรือไม่สามารถส่งมอบได้ และจะดำเนินการคืนเงินตามนโยบายการคืนเงิน</p>
        <h2>5. สิทธิในทรัพย์สินทางปัญญา</h2>
        <p>ชื่อ เครื่องหมาย ระบบ ซอฟต์แวร์ และเนื้อหาของแพลตฟอร์มได้รับความคุ้มครอง ผู้ซื้อได้รับเพียงสิทธิใช้ตาม License ของสินค้า ไม่ได้รับโอนกรรมสิทธิ์หรือลิขสิทธิ์ ห้ามทำซ้ำ แจกจ่าย ขายต่อ เปิดเผยไฟล์ต้นฉบับ หลีกเลี่ยงมาตรการรักษาความปลอดภัย หรือใช้บริการเพื่อการผิดกฎหมาย เว้นแต่ License หรือกฎหมายอนุญาต</p>
        <h2>6. เนื้อหาและการใช้งานที่ห้าม</h2>
        <p>ห้ามอัปโหลดหรือสื่อสารเนื้อหาที่ผิดกฎหมาย ละเมิดสิทธิ เป็นอันตราย หลอกลวง เลือกปฏิบัติ เปิดเผยข้อมูลส่วนบุคคลโดยไม่มีฐานกฎหมาย มีมัลแวร์ หรือรบกวนระบบ แพลตฟอร์มอาจตรวจสอบ ซ่อน ระงับ หรือนำเนื้อหาออกตามนโยบายสินค้าและนโยบายลิขสิทธิ์</p>
        <h2>7. ความพร้อมใช้งานและความรับผิด</h2>
        <p>แพลตฟอร์มพยายามให้บริการอย่างต่อเนื่อง แต่อาจหยุดเพื่อบำรุงรักษา ความปลอดภัย หรือเหตุที่อยู่นอกการควบคุม ไม่มีข้อความใดตัดสิทธิผู้บริโภคตามกฎหมาย ความรับผิดของแต่ละฝ่ายให้เป็นไปตามความเสียหายจริงที่พิสูจน์ได้ สัญญา และกฎหมายที่ใช้บังคับ</p>
        <h2>8. การเปลี่ยนแปลงและกฎหมายที่ใช้บังคับ</h2>
        <p>การเปลี่ยนแปลงสาระสำคัญจะประกาศพร้อมวันมีผล และอาจขอให้ยอมรับใหม่ ข้อกำหนดนี้อยู่ภายใต้กฎหมายไทย ข้อพิพาทให้ดำเนินตามนโยบายข้อร้องเรียนก่อน โดยไม่ตัดสิทธิที่จะใช้หน่วยงานกำกับหรือศาลที่มีเขตอำนาจ</p>
      $html$
    ),
    (
      'seller_agreement',
      'ข้อตกลงการเป็นผู้ขาย E-KRU Marketplace',
      'คุณสมบัติ หน้าที่ มาตรฐานสินค้า ค่าธรรมเนียม การพักยอด และความรับผิดของผู้ขาย',
      $html$
        <h2>1. คุณสมบัติและการแต่งตั้ง</h2><p>ผู้ขายขอใช้แพลตฟอร์มเพื่อเสนอขายทรัพยากรการศึกษา และแต่งตั้งแพลตฟอร์มให้รับคำสั่งซื้อ รับชำระเงิน ออกหลักฐานรายการ และโอนรายรับสุทธิตามนโยบายที่เกี่ยวข้อง ผู้ขายต้องมีความสามารถตามกฎหมายและส่งข้อมูลยืนยันตัวตน ภาษี ที่อยู่ และบัญชีรับเงินที่เป็นของผู้ขายหรือกิจการโดยชอบ</p>
        <h2>2. หน้าที่ของผู้ขาย</h2><ul><li>ให้ข้อมูลร้าน สินค้า ราคา ไฟล์ ตัวอย่าง เงื่อนไข License และข้อมูลภาษีอย่างถูกต้อง</li><li>มีสิทธิหรือหนังสืออนุญาตสำหรับข้อความ รูป เสียง วิดีโอ ฟอนต์ ซอฟต์แวร์ และองค์ประกอบทั้งหมด</li><li>ดูแลคุณภาพ ความปลอดภัย การใช้งานได้จริง และตอบข้อร้องเรียนหรือคำขอหลักฐานภายในเวลาที่แพลตฟอร์มกำหนด</li><li>ไม่ชักชวนให้ชำระเงินนอกระบบเพื่อหลีกเลี่ยงค่าธรรมเนียมหรือมาตรการคุ้มครอง</li></ul>
        <h2>3. การตรวจสอบและเผยแพร่</h2><p>แพลตฟอร์มอาจตรวจด้วยระบบอัตโนมัติหรือบุคคล ขอแก้ไข ขอหลักฐาน ปฏิเสธ ซ่อน หรือนำสินค้าออก การอนุมัติไม่ใช่คำรับรองว่าไม่ละเมิดกฎหมาย และไม่ลดความรับผิดของผู้ขาย การแก้ข้อมูลสำคัญอาจต้องตรวจใหม่ตามที่หน้าจอระบุ</p>
        <h2>4. ราคา ค่าธรรมเนียม และภาษี</h2><p>ผู้ขายกำหนดราคาภายใต้กติกาแพลตฟอร์ม และยอมรับค่าคอมมิชชัน ค่าช่องทางชำระเงิน ภาษี และรายการปรับยอดตามอัตราที่แสดงในหน้าการเงินหรือก่อนยืนยัน ผู้ขายรับผิดชอบการจดทะเบียนและยื่นภาษีของตน แพลตฟอร์มอาจหักภาษี ณ ที่จ่ายหรือออกเอกสารเมื่อกฎหมายกำหนด</p>
        <h2>5. รายรับ การพักยอด และการหักกลบ</h2><p>รายรับพร้อมจ่ายหลังพ้นระยะพักยอดและถึงยอดขั้นต่ำ/รอบโอนที่ตั้งค่าไว้ แพลตฟอร์มอาจพักหรือหักกลบยอดสำหรับการคืนเงิน Chargeback ข้อพิพาท การทุจริต ภาษี ค่าธรรมเนียม หรือยอดติดลบ พร้อมแสดงรายการอ้างอิง ผู้ขายต้องรักษาข้อมูลบัญชีรับเงินให้ถูกต้อง</p>
        <h2>6. ข้อร้องเรียนและการชดใช้</h2><p>ผู้ขายต้องร่วมตรวจสอบและรับผิดชอบความเสียหายจากข้อมูลเท็จ สินค้าบกพร่อง หรือการละเมิดสิทธิที่เกิดจากสินค้าของตน รวมถึงค่าใช้จ่ายที่สมเหตุสมผล เว้นแต่เกิดจากความผิดของแพลตฟอร์ม ผู้ขายมีสิทธิชี้แจงและอุทธรณ์ตามนโยบายข้อร้องเรียน</p>
        <h2>7. การสิ้นสุด</h2><p>ผู้ขายขอปิดร้านได้เมื่อไม่มีภาระค้าง แพลตฟอร์มอาจระงับหรือยกเลิกเมื่อฝ่าฝืนร้ายแรงหรือซ้ำหลายครั้ง ภายหลังสิ้นสุด สิทธิของผู้ซื้อเดิม หลักฐานธุรกรรม ภาระคืนเงิน ภาษี และข้อกำหนดเรื่องทรัพย์สินทางปัญญายังคงมีผลเท่าที่จำเป็น</p>
      $html$
    ),
    (
      'privacy_policy',
      'นโยบายความเป็นส่วนตัว (PDPA)',
      'รายละเอียดการเก็บ ใช้ เปิดเผย เก็บรักษา และสิทธิของเจ้าของข้อมูลส่วนบุคคล',
      $html$
        <h2>1. ขอบเขตและบทบาท</h2><p>นโยบายนี้อธิบายการประมวลผลข้อมูลของผู้เยี่ยมชม สมาชิก ผู้ซื้อ ผู้ขาย บุคลากรโรงเรียน นักเรียน ผู้ปกครอง และผู้ติดต่อ โดยผู้ให้บริการเป็นผู้ควบคุมข้อมูลสำหรับบัญชี Marketplace การซื้อขาย ความปลอดภัย และการตลาดของตน และอาจเป็นผู้ประมวลผลข้อมูลแทนโรงเรียนในฟังก์ชันที่โรงเรียนกำหนดวัตถุประสงค์</p>
        <h2>2. ข้อมูลที่เก็บ</h2><ul><li>ข้อมูลบัญชีและการติดต่อ เช่น ชื่อ อีเมล โทรศัพท์ บทบาท โรงเรียน และข้อมูลยืนยันตัวตน</li><li>ข้อมูลผู้ขาย ภาษี เอกสาร และบัญชีรับเงิน ซึ่งข้อมูลการเงินสำคัญจัดเก็บแบบจำกัดสิทธิหรือเข้ารหัสตามความเหมาะสม</li><li>ข้อมูลคำสั่งซื้อ การชำระเงิน License ดาวน์โหลด คืนเงิน ข้อร้องเรียน และการติดต่อ</li><li>ข้อมูลเทคนิค เช่น IP อุปกรณ์ บันทึกเหตุการณ์ ความปลอดภัย คุกกี้ และการตั้งค่าความยินยอม</li><li>ข้อมูลการศึกษา/ข้อมูลเด็กเฉพาะเมื่อใช้บริการโรงเรียนและมีสิทธิตามกฎหมาย</li></ul>
        <h2>3. วัตถุประสงค์และฐานกฎหมาย</h2><p>เราใช้ข้อมูลเพื่อสร้างและรักษาบัญชี ทำสัญญา ส่งมอบสินค้า รับชำระและโอนเงิน ออกเอกสารทางบัญชี ให้บริการโรงเรียน ป้องกันทุจริต สนับสนุนผู้ใช้ ปฏิบัติตามกฎหมาย และใช้/ต่อสู้สิทธิเรียกร้อง โดยอาศัยการปฏิบัติตามสัญญา หน้าที่ตามกฎหมาย ประโยชน์โดยชอบด้วยกฎหมาย ความยินยอม หรือฐานอื่นที่กฎหมายอนุญาต ข้อมูลอ่อนไหวจะประมวลผลเมื่อมีฐานเฉพาะตามกฎหมาย</p>
        <h2>4. การเปิดเผยและผู้ประมวลผล</h2><p>อาจเปิดเผยแก่ผู้ขายหรือผู้ซื้อเท่าที่จำเป็น ผู้ให้บริการชำระเงิน ธนาคาร Cloud/Storage อีเมล LINE ระบบวิเคราะห์ ผู้ตรวจสอบ ที่ปรึกษา โรงเรียนคู่สัญญา และหน่วยงานรัฐตามกฎหมาย ผู้รับข้อมูลต้องอยู่ภายใต้หน้าที่รักษาความลับและความปลอดภัย การโอนไปต่างประเทศจะใช้มาตรการตามกฎหมายและระดับความคุ้มครองที่เหมาะสม</p>
        <h2>5. ระยะเวลาเก็บและความปลอดภัย</h2><p>เก็บข้อมูลเท่าที่จำเป็นต่อบริการ ระยะสัญญา ภาษี บัญชี การป้องกันทุจริต และอายุความ แล้วลบ ทำลาย หรือทำให้ไม่สามารถระบุตัวบุคคล ใช้มาตรการควบคุมสิทธิ บันทึกการเข้าถึง เข้ารหัส สำรองข้อมูล และทบทวนเหตุการณ์ตามความเสี่ยง แต่ไม่มีระบบใดปลอดภัยสมบูรณ์</p>
        <h2>6. สิทธิของเจ้าของข้อมูล</h2><p>เจ้าของข้อมูลอาจขอเข้าถึง สำเนา แก้ไข ลบ จำกัด คัดค้าน โอนข้อมูล ถอนความยินยอม หรือร้องเรียนต่อสำนักงานคณะกรรมการคุ้มครองข้อมูลส่วนบุคคล ทั้งนี้เป็นไปตามเงื่อนไขกฎหมาย คำขอส่งผ่านอีเมลติดต่อที่แสดงท้ายเอกสาร เราอาจขอยืนยันตัวตนและแจ้งผลภายในกรอบเวลาตามกฎหมาย</p>
        <h2>7. การเปลี่ยนแปลง</h2><p>เมื่อเปลี่ยนวัตถุประสงค์หรือสาระสำคัญ เราจะปรับนโยบาย แจ้งวันมีผล และขอความยินยอมใหม่เมื่อฐานกฎหมายกำหนด</p>
      $html$
    ),
    (
      'copyright_takedown',
      'นโยบายลิขสิทธิ์และการนำเนื้อหาออก',
      'การรับแจ้ง ตรวจสอบ ระงับ นำเนื้อหาออก การชี้แจง และมาตรการสำหรับการละเมิดซ้ำ',
      $html$
        <h2>1. หลักการ</h2><p>ผู้ขายต้องเผยแพร่เฉพาะงานที่ตนสร้างหรือได้รับอนุญาตอย่างเพียงพอ การอ้างแหล่งที่มาเพียงอย่างเดียวไม่แทนการได้รับอนุญาต แพลตฟอร์มเคารพลิขสิทธิ์ เครื่องหมายการค้า และสิทธิอื่น และจะพิจารณาคำร้องโดยเป็นธรรม</p>
        <h2>2. ข้อมูลในคำแจ้ง</h2><p>ผู้ร้องควรส่งชื่อและช่องทางติดต่อ หลักฐานความเป็นเจ้าของ/อำนาจตัวแทน รายละเอียดงานต้นฉบับ URL หรือรหัสสินค้าที่ถูกร้อง คำอธิบายการละเมิด หลักฐานเปรียบเทียบ และคำรับรองโดยสุจริตว่าข้อมูลถูกต้อง หากข้อมูลไม่ครบ เราอาจขอเพิ่มเติมก่อนดำเนินการ</p>
        <h2>3. มาตรการชั่วคราวและการตรวจสอบ</h2><p>เมื่อคำแจ้งมีมูล แพลตฟอร์มอาจซ่อนสินค้า ระงับดาวน์โหลด เก็บรักษาหลักฐาน และแจ้งผู้ขาย ผู้ขายส่งคำชี้แจง ใบอนุญาต ไฟล์ต้นฉบับ หรือหลักฐานอื่นได้ แพลตฟอร์มอาจคืนสถานะ คงการระงับ นำออก คืนเงิน หรือส่งเรื่องให้หน่วยงานที่เกี่ยวข้องตามหลักฐานและกฎหมาย</p>
        <h2>4. การแจ้งเท็จและการละเมิดซ้ำ</h2><p>ห้ามใช้กระบวนการนี้เพื่อกลั่นแกล้ง แข่งขันโดยไม่เป็นธรรม หรือให้ข้อมูลเท็จ ผู้แจ้งและผู้ขายรับผิดชอบคำรับรองของตน บัญชีที่ละเมิดซ้ำหรือร้ายแรงอาจถูกจำกัด พักยอด หรือยกเลิก โดยผู้ได้รับผลมีสิทธิอุทธรณ์พร้อมหลักฐานใหม่</p>
        <h2>5. การสงวนสิทธิ</h2><p>กระบวนการภายในไม่ใช่คำวินิจฉัยกรรมสิทธิ์และไม่ตัดสิทธิของคู่กรณีในการดำเนินการตามกฎหมาย แพลตฟอร์มอาจเปิดเผยข้อมูลเท่าที่จำเป็นต่อคู่กรณี ที่ปรึกษา หรือเจ้าหน้าที่ตามกฎหมาย</p>
      $html$
